package org.mockito.internal.creation;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.MockSettings;
import org.mockito.exceptions.Reporter;
import org.mockito.internal.util.MockName;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.internal.creation.MockSettingsImpl.serializable;

public class MockSettingsImpl_serializable_TriageGen1Test {

    @Test
    public void testSerializable() {
        // Since MockSettingsImpl is an internal Mockito class, 
        // we instantiate it via its constructor or a mock-creating path.
        // However, based on the provided API, we test the behavior of the serializable() method.

        MockSettingsImpl settings = new MockSettingsImpl();

        // Pre-condition: should not be serializable initially
        // (Assuming default behavior of a new MockSettingsImpl instance)

        // Execute
        MockSettings serializableSettings = settings.serializable();

        // Verify return type and behavior
        assertTrue("The settings should be marked as serializable", serializableSettings.isSerializable());

        // Verify that Serializable.class was added to extra interfaces
        Class<?>[] extraInterfaces = serializableSettings.getExtraInterfaces();
        Class<?>[] expected = { Serializable.class };
        assertArrayEquals("The extra interfaces should contain java.io.Serializable", expected, extraInterfaces);
    }

    @Test
    public void testSerializableChainability() {
        MockSettingsImpl settings = new MockSettingsImpl();

        // Test that calling serializable returns a MockSettings object that allows further chaining/checking
        MockSettings settingsWithSerializable = settings.serializable();

        // Verify that the returned object is indeed the same type and has the property
        assertTrue(settingsWithSerializable.isSerializable());
    }
}
